package com.ewu.matching.controller;
import com.ewu.matching.dto.request.EndorseSkillRequest;import com.ewu.matching.dto.response.SkillEndorsementResponse;import com.ewu.matching.service.SkillEndorsementService;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.List;
@Tag(name="Skill Endorsements") @RestController @RequestMapping("/api/endorsements") @RequiredArgsConstructor @PreAuthorize("isAuthenticated()")
public class SkillEndorsementController {private final SkillEndorsementService service;@PostMapping public ResponseEntity<SkillEndorsementResponse> endorse(@Valid @RequestBody EndorseSkillRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.endorse(r.studentId(),r.skillId()));}@DeleteMapping("/students/{studentId}/skills/{skillId}") public ResponseEntity<Void> remove(@PathVariable Long studentId,@PathVariable Long skillId){service.removeMine(studentId,skillId);return ResponseEntity.noContent().build();}@GetMapping("/students/{studentId}/skills/{skillId}") public ResponseEntity<List<SkillEndorsementResponse>> list(@PathVariable Long studentId,@PathVariable Long skillId){return ResponseEntity.ok(service.list(studentId,skillId));}}
